//! Tests for the GPU shader-generation backend.
//!
//! Extracted from `gpu.rs` during the STRUCT.1 split (TODO6.md). The
//! tests module sits as a child of `gpu`, so `use super::*` resolves to
//! the same `GpuProcessor` / `GpuOp` / `GpuTexture` items it did when the
//! block lived inline.

use super::*;
use crate::Transform;
use crate::transform::CdlTransform;

#[test]
fn test_gpu_language_version() {
    assert!(GpuLanguage::Glsl330.version_directive().contains("330"));
    assert!(
        GpuLanguage::GlslEs300
            .version_directive()
            .contains("300 es")
    );
}

#[test]
fn test_gpu_language_is_glsl() {
    assert!(GpuLanguage::Glsl330.is_glsl());
    assert!(GpuLanguage::GlslEs300.is_glsl());
    assert!(!GpuLanguage::Hlsl50.is_glsl());
    assert!(!GpuLanguage::Metal.is_glsl());
}

#[test]
fn test_hlsl_generation() {
    // Create a simple CDL transform
    let cdl = Transform::Cdl(CdlTransform {
        slope: [1.1, 1.0, 0.9],
        offset: [0.01, 0.0, -0.01],
        power: [1.0, 1.0, 1.0],
        saturation: 1.0,
        ..Default::default()
    });

    let processor = Processor::from_transform(&cdl, crate::TransformDirection::Forward).unwrap();
    let gpu = GpuProcessor::from_processor(&processor).unwrap();
    let shader = gpu.generate_shader(GpuLanguage::Hlsl50).unwrap();

    let code = shader.fragment_code();

    // Verify HLSL-specific syntax
    assert!(code.contains("HLSL 5.0 Generated by vfx-ocio"));
    assert!(code.contains("Texture2D u_inputTexture"));
    assert!(code.contains("SamplerState"));
    assert!(code.contains("float4 ocio_transform(float4 color)"));
    assert!(code.contains("float4 main(PSInput input) : SV_TARGET"));
    assert!(code.contains(".Sample("));
    assert!(code.contains("float4(")); // HLSL uses float4 not vec4
}

#[test]
fn test_metal_generation() {
    // Create a simple CDL transform
    let cdl = Transform::Cdl(CdlTransform {
        slope: [1.1, 1.0, 0.9],
        offset: [0.01, 0.0, -0.01],
        power: [1.0, 1.0, 1.0],
        saturation: 1.0,
        ..Default::default()
    });

    let processor = Processor::from_transform(&cdl, crate::TransformDirection::Forward).unwrap();
    let gpu = GpuProcessor::from_processor(&processor).unwrap();
    let shader = gpu.generate_shader(GpuLanguage::Metal).unwrap();

    let code = shader.fragment_code();

    // Verify Metal-specific syntax
    assert!(code.contains("Metal Shading Language Generated by vfx-ocio"));
    assert!(code.contains("#include <metal_stdlib>"));
    assert!(code.contains("using namespace metal;"));
    assert!(code.contains("[[position]]"));
    assert!(code.contains("[[texture(0)]]"));
    assert!(code.contains("[[sampler(0)]]"));
    assert!(code.contains("fragment float4 fragmentMain"));
    assert!(code.contains(".sample(")); // Metal uses .sample() not .Sample()
    assert!(code.contains("float4(")); // Metal uses float4 not vec4
}

#[test]
fn test_hlsl_transfer_srgb() {
    use crate::processor::TransferStyle;

    let gpu = GpuProcessor {
        ops: vec![GpuOp::Transfer {
            style: TransferStyle::Srgb,
            forward: true,
        }],
        textures: vec![],
    };

    let shader = gpu.generate_shader(GpuLanguage::Hlsl50).unwrap();
    let code = shader.fragment_code();

    // Verify sRGB OETF in HLSL
    assert!(code.contains("sRGB OETF"));
    assert!(code.contains("lerp(")); // HLSL uses lerp not mix
    // PLAN9.md O2: toe_power now mirrors (sign(x) * f(abs(x))) instead of clamping to zero, so the
    // old `float3(0.0, 0.0, 0.0)` clamp-guard splat is gone by design - check the mirror itself and
    // a still-present splatted constant (the power exponent) for "HLSL explicit vec components".
    assert!(code.contains("sign(color.rgb)"));
    assert!(code.contains("abs(color.rgb)"));
    assert!(code.contains("float3(0.416666666667, 0.416666666667, 0.416666666667)"));
}

