#[test]
fn test_hlsl_all_transfer_functions() {
    use crate::processor::TransferStyle;

    // Test all transfer functions generate valid HLSL
    let styles = [
        TransferStyle::Srgb,
        TransferStyle::Rec709,
        TransferStyle::Rec2020,
        TransferStyle::Gamma22,
        TransferStyle::Gamma24,
        TransferStyle::Gamma26,
        TransferStyle::Rec1886,
        TransferStyle::Pq,
        TransferStyle::Hlg,
        TransferStyle::AcesCct,
        TransferStyle::AcesCc,
        TransferStyle::LogC3,
        TransferStyle::LogC4,
        TransferStyle::SLog3,
        TransferStyle::VLog,
        TransferStyle::Log3G10,
        TransferStyle::BmdFilmGen5,
        TransferStyle::AppleLog,
        TransferStyle::CanonCLog2,
        TransferStyle::CanonCLog3,
    ];

    for style in styles {
        for forward in [true, false] {
            let gpu = GpuProcessor {
                ops: vec![GpuOp::Transfer { style, forward }],
                textures: vec![],
            };

            let shader = gpu.generate_shader(GpuLanguage::Hlsl50).unwrap();
            let code = shader.fragment_code();

            // Verify no "TODO" stubs - all functions should be fully implemented
            assert!(
                !code.contains("TODO"),
                "Transfer {:?} {} contains TODO stub in HLSL",
                style,
                if forward { "forward" } else { "inverse" }
            );

            // Verify HLSL syntax (lerp instead of mix)
            if code.contains("lerp(") || code.contains("pow(") {
                // Good - using HLSL functions
            }
        }
    }
}

