#[test]
fn test_grading_rgb_curve_gpu() {
    use crate::transform::{GradingRgbCurveTransform, GradingToneStyle};

    // Create S-curve transform
    let gc = Transform::GradingRgbCurve(GradingRgbCurveTransform {
        name: String::new(),
        style: GradingToneStyle::Log,
        red: vec![[0.0, 0.1], [0.5, 0.5], [1.0, 0.9]],
        green: vec![[0.0, 0.0], [1.0, 1.0]], // Identity
        blue: vec![[0.0, 0.0], [1.0, 1.0]],
        master: vec![[0.0, 0.0], [1.0, 1.0]],
        red_slopes: vec![],
        green_slopes: vec![],
        blue_slopes: vec![],
        master_slopes: vec![],
        bypass_lin_to_log: false,
        direction: crate::TransformDirection::Forward,
    });

    let processor = Processor::from_transform(&gc, crate::TransformDirection::Forward).unwrap();
    let gpu = GpuProcessor::from_processor(&processor).unwrap();

    // GradingRgbCurve uses uniform BSpline data (no LUT textures).
    assert!(
        gpu.textures.is_empty(),
        "GradingRgbCurve should not create LUT textures"
    );

    // Test GLSL generation
    let shader = gpu.generate_shader(GpuLanguage::Glsl330).unwrap();
    let code = shader.fragment_code();
    assert!(
        code.contains("GradingRgbCurve"),
        "GLSL should contain GradingRgbCurve comment"
    );

    // Test HLSL generation
    let shader = gpu.generate_shader(GpuLanguage::Hlsl50).unwrap();
    let code = shader.fragment_code();
    assert!(
        code.contains("GradingRgbCurve"),
        "HLSL should contain GradingRgbCurve comment"
    );

    // Test Metal generation
    let shader = gpu.generate_shader(GpuLanguage::Metal).unwrap();
    let code = shader.fragment_code();
    assert!(
        code.contains("GradingRgbCurve"),
        "Metal should contain GradingRgbCurve comment"
    );
}

